create or replace function public.seed_family_defaults(p_family_id uuid) returns void language plpgsql security definer set search_path='' as $$declare names text[]:=array['Sinh hoạt gia đình','Con cái','Du lịch','Hiếu hỉ & quan hệ','Nhà cửa & gia dụng','Xe cộ','Sức khỏe gia đình','Thai sản','Đầu tư','Khác']; types text[]:=array['Ăn uống','Thực phẩm','Điện','Nước','Internet','Di chuyển','Xăng','ETC','Khách sạn','Vé máy bay','Quần áo','Giày dép','Gia dụng','Giáo dục','Sức khỏe','Mỹ phẩm','Giải trí','Đồ chơi','Tiêu dùng','Thú cưng','Đám cưới','Sinh nhật','Lì xì','Quà','Đầu tư chứng khoán','Đầu tư vàng','Khác'];n text;i int:=0;begin if not public.is_family_owner(p_family_id) then raise exception 'FORBIDDEN';end if;foreach n in array names loop insert into public.purposes(family_id,name,code,sort_order) values(p_family_id,n,'purpose-'||i,i) on conflict(family_id,code) do nothing;i:=i+1;end loop;i:=0;foreach n in array types loop insert into public.expense_types(family_id,name,code,sort_order) values(p_family_id,n,'expense-'||i,i) on conflict(family_id,code) do nothing;i:=i+1;end loop;foreach n in array array['Chuyển khoản','Thẻ tín dụng','Trả góp','Urbox','Tiền mặt'] loop insert into public.payment_methods(family_id,name,sort_order) values(p_family_id,n,i) on conflict(family_id,name) do nothing;i:=i+1;end loop;end$$;grant execute on function public.seed_family_defaults(uuid) to authenticated;
